constexpr std::array<FieldSpec,3> defs{{{1,AtomType::Reference,dynamic_tree_kind,3,3,false},{2,AtomType::Reference,moves_kind,1,1,false},{3,AtomType::Reference,pair_set_kind,1,1,false}}};
bool overlap(const void*a,size_t n,const void*b,size_t m)noexcept{auto x=reinterpret_cast<uintptr_t>(a),y=reinterpret_cast<uintptr_t>(b);return n&&m&&(x<=y?y-x<n:x-y<m);}
struct Range {const void *p;size_t n;};
Status ids_valid(const BroadPhaseIds &ids)noexcept{for(size_t i=0;i<3;++i){auto id=ids.trees[i];if(id.kind!=dynamic_tree_kind||!id.simulation||!id.generation)return fail(Error::IncompatibleSchema);for(size_t j=0;j<i;++j)if(ids.trees[j].simulation==id.simulation)return fail(Error::InvalidArgument);}if(ids.moves.kind!=moves_kind||!ids.moves.simulation||!ids.moves.generation||ids.pairs.kind!=pair_set_kind||!ids.pairs.simulation||!ids.pairs.generation)return fail(Error::IncompatibleSchema);return {};}
Status validate(const BroadPhaseParts&p,const BroadPhaseMaps &maps,TreeCaptureBoundary b,BroadPhaseScratch s,const void* output=nullptr,size_t output_size=0)noexcept{
 if(!b.physics_jobs_drained||!b.rebuild_drained||b.heuristic||!maps.shapes)return fail(Error::NotReady);if(auto r=ids_valid(p.ids);!r)return r;
 size_t capacity=0;for(size_t t=0;t<3;++t){const auto&n=p.trees[t];if(!maps.nodes[t]||!maps.proxies[t]||n.nodeCapacity<0||n.nodeCapacity>100000||n.nodeCount<0||n.proxyCount<0||n.rebuildCapacity<0||n.rebuildCapacity>100000||(!n.nodes&&n.nodeCapacity)||(!n.leafIndices&&n.rebuildCapacity)||(!n.leafCenters&&n.rebuildCapacity)||n.leafBoxes||n.binIndices)return fail(Error::InvalidArgument);capacity+=size_t(n.nodeCapacity);}
 if(p.moves.capacity>100000||p.moves.count>p.moves.capacity||(!p.moves.moves&&p.moves.capacity)||p.pairs.capacity<16||p.pairs.capacity>131072||(p.pairs.capacity&(p.pairs.capacity-1))||p.pairs.count>p.pairs.capacity/2||!p.pairs.items)return fail(Error::InvalidArgument);
 if(s.identities.size()<capacity+p.pairs.count||s.order.size()<p.moves.count)return fail(Error::CapacityExceeded);
 const std::array<Range,3> scratch{{{s.marks.data(),s.marks.size_bytes()},{s.order.data(),s.order.size_bytes()},{s.identities.data(),s.identities.size_bytes()}}};
 for(size_t i=0;i<3;++i)for(size_t j=i+1;j<3;++j)if(overlap(scratch[i].p,scratch[i].n,scratch[j].p,scratch[j].n))return fail(Error::InvalidArgument);
 auto safe=[&](const void*ptr,size_t bytes){if(overlap(ptr,bytes,output,output_size))return false;for(auto r:scratch)if(overlap(ptr,bytes,r.p,r.n))return false;return true;};
 if(!safe(&p,sizeof(p))||!safe(&maps,sizeof(maps))||!safe(p.moves.moves,size_t(p.moves.capacity)*sizeof(int))||!safe(p.pairs.items,size_t(p.pairs.capacity)*sizeof(b2SetItem)))return fail(Error::InvalidArgument);
 for(size_t t=0;t<3;++t){const auto&n=p.trees[t];const auto &bits=p.moves.bits[t];if(bits.blockCount>bits.blockCapacity||bits.blockCapacity>1563||(!bits.bits&&bits.blockCapacity))return fail(Error::InvalidArgument);if(!safe(n.nodes,size_t(n.nodeCapacity)*sizeof(b2TreeNode))||!safe(n.leafIndices,size_t(n.rebuildCapacity)*sizeof(int32_t))||!safe(n.leafCenters,size_t(n.rebuildCapacity)*sizeof(b2Vec2))||!safe(bits.bits,size_t(bits.blockCapacity)*sizeof(uint64_t)))return fail(Error::InvalidArgument);}
 std::array<Range,14> owned{};for(size_t t=0;t<3;++t){const auto&n=p.trees[t];owned[t*4]={n.nodes,size_t(n.nodeCapacity)*sizeof(b2TreeNode)};owned[t*4+1]={n.leafIndices,size_t(n.rebuildCapacity)*sizeof(int32_t)};owned[t*4+2]={n.leafCenters,size_t(n.rebuildCapacity)*sizeof(b2Vec2)};owned[t*4+3]={p.moves.bits[t].bits,size_t(p.moves.bits[t].blockCapacity)*sizeof(uint64_t)};}owned[12]={p.moves.moves,size_t(p.moves.capacity)*sizeof(int)};owned[13]={p.pairs.items,size_t(p.pairs.capacity)*sizeof(b2SetItem)};for(size_t i=0;i<owned.size();++i)for(size_t j=i+1;j<owned.size();++j)if(overlap(owned[i].p,owned[i].n,owned[j].p,owned[j].n))return fail(Error::InvalidArgument);
 size_t used=0;for(size_t t=0;t<3;++t){const auto&n=p.trees[t];if(auto r=validate_tree_topology(std::span(n.nodes,size_t(n.nodeCapacity)),n.root,n.freeList,uint32_t(n.nodeCount),uint32_t(n.proxyCount),s.marks,s.order);!r)return r;for(int i=0;i<n.nodeCapacity;++i){auto id=maps.nodes[t]->canonical(uint32_t(i));if(!id||id->kind!=tree_node_kind)return fail(Error::StaleGeneration);s.identities[used++]=id->simulation;}}
 std::sort(s.identities.begin(),s.identities.begin()+used);for(size_t i=1;i<used;++i)if(s.identities[i]==s.identities[i-1])return fail(Error::InvalidArgument);
 // Proxy identities and shape identities are globally distinct across body-type trees.
 size_t leaves=0;for(size_t t=0;t<3;++t)for(int i=0;i<p.trees[t].nodeCapacity;++i){const auto&n=p.trees[t].nodes[i];if(!(n.flags&b2_leafNode))continue;if(n.userData>INT_MAX)return fail(Error::InvalidArgument);auto proxy=maps.proxies[t]->canonical(uint32_t(i)),shape=maps.shapes->canonical(uint32_t(n.userData));if(!proxy||proxy->kind!=shape_proxy_kind||!shape||shape->kind!=shape_kind)return fail(Error::StaleGeneration);s.identities[leaves++]=proxy->simulation;}
 std::sort(s.identities.begin(),s.identities.begin()+leaves);for(size_t i=1;i<leaves;++i)if(s.identities[i]==s.identities[i-1])return fail(Error::InvalidArgument);
 used=0;for(size_t t=0;t<3;++t)for(int i=0;i<p.trees[t].nodeCapacity;++i)if(p.trees[t].nodes[i].flags&b2_leafNode)s.identities[used++]=p.trees[t].nodes[i].userData;
 std::sort(s.identities.begin(),s.identities.begin()+leaves);for(size_t i=1;i<leaves;++i)if(s.identities[i]==s.identities[i-1])return fail(Error::InvalidArgument);
 uint64_t setbits=0;for(const auto &bits:p.moves.bits){for(uint32_t i=0;i<bits.blockCount;++i)setbits+=std::popcount(bits.bits[i]);for(uint32_t i=bits.blockCount;i<bits.blockCapacity;++i)if(bits.bits[i])return fail(Error::NonCanonical);}if(setbits!=p.moves.count)return fail(Error::InvalidArgument);
 for(size_t i=0;i<p.moves.count;++i){int key=p.moves.moves[i];if(key<0)return fail(Error::InvalidArgument);auto t=unsigned(key)&3,slot=unsigned(key)>>2;if(t>=3||slot>=unsigned(p.trees[t].nodeCapacity)||!(p.trees[t].nodes[slot].flags&b2_leafNode)||!b2GetBit(&p.moves.bits[t],slot))return fail(Error::InvalidArgument);s.order[i]=unsigned(key);}
 std::sort(s.order.begin(),s.order.begin()+p.moves.count);for(size_t i=1;i<p.moves.count;++i)if(s.order[i]==s.order[i-1])return fail(Error::InvalidArgument);
 size_t pairs=0;for(uint32_t i=0;i<p.pairs.capacity;++i){auto key=p.pairs.items[i].key;if(!key)continue;if(pairs>=p.pairs.count)return fail(Error::InvalidArgument);uint32_t a=uint32_t(key>>32),c=uint32_t(key);if(a>=c||!std::binary_search(s.identities.begin(),s.identities.begin()+leaves,uint64_t(a))||!std::binary_search(s.identities.begin(),s.identities.begin()+leaves,uint64_t(c))||!b2ContainsKey(&p.pairs,key))return fail(Error::InvalidArgument);s.identities[capacity+pairs++]=key;}
 if(pairs!=p.pairs.count)return fail(Error::InvalidArgument);auto keys=s.identities.subspan(capacity,pairs);std::sort(keys.begin(),keys.end());for(size_t i=1;i<pairs;++i)if(keys[i]==keys[i-1])return fail(Error::InvalidArgument);return {};
}
