BroadPhaseImage::BroadPhaseImage()noexcept{fields={Field{1,std::span(atoms).subspan(0,3)},Field{2,std::span(atoms).subspan(3,1)},Field{3,std::span(atoms).subspan(4,1)}};record.fields=fields;}
std::span<const FieldSpec> broadphase_fields()noexcept{return defs;}
Status capture_broadphase(const SpBroadPhaseView&n,Identity id,const BroadPhaseIds &ids,const BroadPhaseMaps &maps,TreeCaptureBoundary b,BroadPhaseScratch s,BroadPhaseImage &out)noexcept{
 if(id.kind!=broadphase_kind||!id.simulation||!id.generation||n.moveResults||n.movePairs||n.moveArray.count<0||n.moveArray.capacity<0)return fail(Error::InvalidArgument);
 if(overlap(&n,sizeof(n),s.marks.data(),s.marks.size_bytes())||overlap(&n,sizeof(n),s.order.data(),s.order.size_bytes())||overlap(&n,sizeof(n),s.identities.data(),s.identities.size_bytes())||overlap(&out,sizeof(out),&maps,sizeof(maps))||overlap(&out,sizeof(out),&n,sizeof(n))||overlap(&out,sizeof(out),s.marks.data(),s.marks.size_bytes())||overlap(&out,sizeof(out),s.order.data(),s.order.size_bytes())||overlap(&out,sizeof(out),s.identities.data(),s.identities.size_bytes()))return fail(Error::InvalidArgument);
 BroadPhaseParts p{};p.ids=ids;for(size_t t=0;t<3;++t){p.trees[t]=n.trees[t];p.moves.bits[t]=n.movedProxies[t];}p.moves.moves=n.moveArray.data;p.moves.count=uint32_t(n.moveArray.count);p.moves.capacity=uint32_t(n.moveArray.capacity);p.pairs=n.pairSet;if(auto r=validate(p,maps,b,s,&out,sizeof(out));!r)return r;for(size_t t=0;t<3;++t)out.atoms[t]={0,ids.trees[t]};out.atoms[3]={0,ids.moves};out.atoms[4]={0,ids.pairs};out.record.identity=id;return {};
}
Result<SpBroadPhaseView> restore_broadphase(const Record&r,const BroadPhaseParts&p,const BroadPhaseMaps &maps,TreeCaptureBoundary b,BroadPhaseScratch s)noexcept{
 if(r.identity.kind!=broadphase_kind||!r.identity.simulation||!r.identity.generation||r.fields.size()!=3)return fail(Error::IncompatibleSchema);for(size_t f=0;f<3;++f){if(r.fields[f].id!=defs[f].id||r.fields[f].atoms.size()!=defs[f].minimum_atoms)return fail(Error::IncompatibleSchema);for(size_t i=0;i<r.fields[f].atoms.size();++i){auto a=r.fields[f].atoms[i];auto id=f==0?p.ids.trees[i]:(f==1?p.ids.moves:p.ids.pairs);if(a.bits||a.identity!=id)return fail(Error::StaleGeneration);}}
 for(auto field:r.fields){for(auto range:std::array<Range,3>{{{s.marks.data(),s.marks.size_bytes()},{s.order.data(),s.order.size_bytes()},{s.identities.data(),s.identities.size_bytes()}}})if(overlap(range.p,range.n,&r,sizeof(r))||overlap(range.p,range.n,r.fields.data(),r.fields.size_bytes())||overlap(range.p,range.n,field.atoms.data(),field.atoms.size_bytes()))return fail(Error::InvalidArgument);}
 if(auto v=validate(p,maps,b,s);!v)return fail(v.error());SpBroadPhaseView result{};for(size_t t=0;t<3;++t){result.trees[t]=p.trees[t];result.movedProxies[t]=p.moves.bits[t];}result.moveArray.data=p.moves.moves;result.moveArray.count=int(p.moves.count);result.moveArray.capacity=int(p.moves.capacity);result.pairSet=p.pairs;return result;
}
